const rotatePt = (pt, c, deg) => {
  if (!deg) return { x: pt.x, y: pt.y };
  const r = deg * Math.PI / 180, cs = Math.cos(r), sn = Math.sin(r);
  const dx = pt.x - c.x, dy = pt.y - c.y;
  return { x: Math.round(c.x + dx * cs - dy * sn), y: Math.round(c.y + dx * sn + dy * cs) };
};
