  const cx = a.x + a.w / 2, cy = a.y + a.h / 2;
  const far = { x: Math.round(2 * cx - shoulder.x), y: Math.round(2 * cy - shoulder.y) }; // hand end — the opposite side, sweeps around the shoulder
