              {asset.type === "skin" && <label className="chk"><input type="checkbox" checked={!!sel.hideIfHat} onChange={(e) => updSel({ hideIfHat: e.target.checked })} /> Hide if hat <span className="hint2">(e.g. top of the hair)</span></label>}
